import {PLACES} from './data.js';
import {PHOTOS,PLACE_CONTENT} from './place-content.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ext=(url,label)=>`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`;
export function photoFor(id){const p=PHOTOS[id];if(!p)return '';return `<figure class="place-photo"><a href="${esc(p.file)}" target="_blank" rel="noopener" aria-label="放大${esc(PLACES[id]?.name||id)}照片"><img src="${esc(p.file)}" alt="${esc(p.caption)}" loading="lazy" decoding="async"></a><figcaption>${esc(p.caption)}<br>${ext(p.source,p.author)} · ${ext(p.licenseUrl,p.license)} · 裁切预览，点图看全图${id==='kong'?'<strong class="photo-warning">这是2010年资料照片：旧招牌的01:00不适用，本次按22:45关门并电话确认末单。</strong>':''}</figcaption></figure>`;}
export function reviewFor(id){const c=PLACE_CONTENT[id];if(!c?.reviews?.length)return '';return `<div class="real-review"><h3>公开点评摘意</h3>${c.reviews.map(r=>`<p>${esc(r.text)}</p><div class="review-credit">${ext(r.url,r.author+' · '+r.platform)} · ${esc(r.date||r.dateLabel||'原页未标日期')}</div>`).join('')}<small>个人或媒体的当次体验，本站转述；不是本工具实测，也不代表所有人的评价。</small></div>`;}
export function placeDetails(id){const c=PLACE_CONTENT[id];if(!c&&!PHOTOS[id])return '';return `<details class="place-details"><summary>看实景照片、介绍与点评</summary>${photoFor(id)}${c?.intro?'<p>'+esc(c.intro)+'</p>':''}${reviewFor(id)}</details>`;}
const maps={
 'west-kowloon-b2':['西九龙B2抵港大堂','https://www.highspeed.mtr.com.hk/res/pdf/WEK-station-layout-B2.pdf'],
 'west-kowloon-area':['西九龙与九龙站周边','https://www.highspeed.mtr.com.hk/res/pdf/WEK-location-map.pdf'],
 kowloon:['九龙站：东涌线与机场快线分开','https://www.mtr.com.hk/archive/ch/services/layouts/kow.pdf'],
 'hong-kong':['香港站：往中环的站内通道','https://www.mtr.com.hk/archive/ch/services/layouts/hok.pdf'],
 'sai-ying-pun':['西营盘站出口位置','https://www.mtr.com.hk/archive/ch/services/layouts/syp.pdf']
};
function mapPhoto(id){const [name,url]=maps[id];return `<figure class="route-map"><a href="./maps/${id}.png" target="_blank" rel="noopener" aria-label="放大${name}"><img src="./maps/${id}.png" alt="港铁官方图：${name}" loading="lazy"></a><figcaption>点图放大 · ${ext(url,'港铁官方原图 / PDF')} · © MTR</figcaption></figure>`;}
export function renderArrival(){return `<section class="arrival-guide" id="arrival-guide"><div class="section-bar"><h2>22日抵港 · 跟着图走到酒店</h2><span>2人 · 带行李</span></div><div class="alert"><strong>先选交通：吃华乐的时间比较紧</strong><p>华乐当前资料为16:00收档，末单未确认。默认行程安排出关后两人打车到酒店，争取15:30到店；通关或路况慢就跳过。若想省钱走下方港铁路线，从公共抵港大堂到酒店另预留55–75分钟、每人约HK$25–35（估算），赶不上华乐属正常，不要赶路。</p></div><div class="line-route" aria-label="乘车线路"><span>西九龙</span><i>步行</i><span class="tung">九龙站</span><i>东涌线 · 往香港</i><span class="tung">香港站</span><i>站内步行换乘</i><span class="island">中环</span><i>港岛线 · 往坚尼地城</i><span class="island">西营盘 A1</span></div><p class="muted">这里的时间是预留值。图示来自港铁，现场临时围封、工作人员指示优先；截图不是实时导航。</p><div class="arrival-steps">
<article class="guide-step"><div class="step-label">01 · 13:44下车</div><h3>B4月台，去B2办理出入境</h3><p>拿齐行李，跟随「抵港 / Arrivals」指示，经扶梯或升降机由B4上B2。按现场通道依次办理内地出境、香港入境及相应海关手续，再经出闸口进入公共抵港大堂。有需申报物品按海关指示走申报通道。</p><p>把通行证、有效签注及购票证件放在方便取用的位置。预留45–75分钟或更多；13:44不是出关时间。</p><div class="signwords">辨认字样：抵港 Arrivals · B2</div>${mapPhoto('west-kowloon-b2')}</article>
<article class="guide-step"><div class="step-label">02 · 公共大堂出发</div><h3>去九龙站，认准L1的M出口</h3><p>若坐港铁，出关后找「九龙站 / Kowloon Station」「圆方 / ELEMENTS」指示，经升降机或扶梯去L1，沿M出口天桥方向走到圆方，再跟九龙站指示入站，步行约10–20分钟。</p><p>西九龙是高铁站，九龙才是本段港铁站；B2的A出口指向柯士甸站，不是本条路线。拖箱或找不到升降机时问服务台前往L1 M出口的无障碍路线。</p><div class="signwords">辨认字样：M · 九龍站 · ELEMENTS</div>${mapPhoto('west-kowloon-area')}</article>
<article class="guide-step"><div class="step-label">03 · 九龙站上车</div><h3>东涌线往「香港」，坐一站</h3><p>找橙色「东涌线 / Tung Chung Line」，用八达通或按售票机指示购票入闸，目的地西营盘。看月台屏幕，乘往「香港 / Hong Kong」方向，下一站香港下车。</p><p>九龙站同时有机场快线，去酒店这段不要上机场快线，也不要乘东涌方向。上车前以月台终点站字样再次确认。</p><div class="signwords tung">東涌綫 Tung Chung Line · 往香港</div>${mapPhoto('kowloon')}</article>
<article class="guide-step"><div class="step-label">04 · 香港站换乘</div><h3>站内走到中环，换港岛线</h3><p>下车后跟「中环站 / Central」「港岛线 / Island Line」指示，经站内换乘通道走到中环，预留10–15分钟步行。沿付费区换乘路线走，无需走出街面。</p><p>到中环后乘蓝色港岛线往「坚尼地城 / Kennedy Town」：中环 → 上环 → 西营盘，两站后下车。</p><div class="signwords island">港島綫 Island Line · 往堅尼地城</div>${mapPhoto('hong-kong')}</article>
<article class="guide-step"><div class="step-label">05 · 西营盘出站</div><h3>找A1，沿皇后大道西到东边街</h3><p>下车后按「A1 皇后大道西」指示走，站内通道较长，出站步行另留5–10分钟。酒店官网的街面走法：A1出来右转，沿皇后大道西到第一个路口，东边街右转下坡，伯惠酒店在左手边11号。</p><p>拖箱请优先使用可用升降机；若无障碍路线从别的出口出站，重新打开步行导航，不硬套A1的转弯方向。</p><div class="signwords">A1 · 皇后大道西 · 東邊街11號</div>${mapPhoto('sai-ying-pun')}</article>
<article class="guide-step"><div class="step-label">06 · 到店安置</div><h3>伯惠酒店，先存包再决定下午行程</h3><p>向前台出示订单，核对入住人、房间和25日行李寄存。若房间未就绪，可询问先寄存行李。华乐在上环东街16号，和酒店的东边街是不同街道。</p><div class="driver-card"><small>给司机 / 问路时出示</small><strong>伯惠酒店 WE Hotel</strong><p>西營盤東邊街11號</p><a href="tel:+85239750088">酒店 +852 3975 0088</a></div><button class="button primary" data-action="place-nav" data-place="hotel">打开酒店导航</button><p>${ext('https://www.wehotel.hk/zh-cn/location-sc','酒店官方A1步行说明')} · ${ext('https://www.highspeed.mtr.com.hk/sc/guide/process-arrival.html','高铁官方抵港流程')}</p></article></div>
<div class="taxi-guide side-card"><h3>直接打车：抵港与晚间接站都适用</h3><p>在B2公共抵港大堂跟「的士 / Taxi」指示到正规候车区排队。市区的士可到西营盘，向司机出示完整地址；不要跟随拉客者离开队列。白天两人去酒店、晚上四人去光记，车程通常预留20–35分钟，另加排队与堵车；每车先预留HK$130–200，实际按表、隧道费及行李附加费结算。</p><p><strong>后排也必须系安全带，包括中间座位。</strong>四位成人通常前排1人、后排3人，各占一个座位，出发前扣好各自的安全带。行李不能安全放下时分两车。${ext('https://www.td.gov.hk/filemanager/sc/content_276/guidebook_202610.pdf','运输署的士服务指引')}</p><div class="driver-card"><small>22日接人后给司机看</small><strong>光記食店</strong><p>西營盤水街6B號地下</p><a href="tel:+85225486103">先确认末单 +852 2548 6103</a></div></div></section>`;}
export function renderPlaces(){const ids=['tai','temple','park','taikwun','statue','pier','tst'];return `<div class="view-heading"><h1>街道与景点</h1><p>跟着行程认识街区。照片均为有日期和来源的实景资料图，不代表本次活动布置；点照片可放大。</p></div><div class="places-grid">${ids.map(id=>{const c=PLACE_CONTENT[id]||{};return `<article class="food-card">${photoFor(id)}<div class="food-content"><span class="eyebrow">${['tai','temple'].includes(id)?'22日 · 抵港散步':id==='park'?'23日 · 饭后散步':'24日 · 会议之后'}</span><h2>${esc(PLACES[id].name)}</h2><p>${esc(c.intro)}</p>${id==='statue'?'<p class="food-backup">24日周二安排看冬日灯饰，19:30目标场次；当日没有中环圣诞市集。图中日常广场不是2026年布置。</p>':''}${id==='taikwun'?'<p class="food-backup">晚间以庭院和建筑为主，展厅通常19:00关闭，不能保证看展。</p>':''}${reviewFor(id)}<div class="food-actions"><button class="button primary" data-action="place-nav" data-place="${id}">地点导航</button><button class="button" data-action="place-add" data-place="${id}">加入行程</button></div>${(c.sources||[]).map(s=>ext(s.url,s.label)).join(' · ')}</div></article>`;}).join('')}</div>`;}
